          <input type="text" [value]="country()" (input)="country.set($any($event.target).value)" required />
        </label>
        <label>
          E-Mail
          <input type="email" [value]="email()" (input)="email.set($any($event.target).value)" required />
        </label>

        @if (cartIsEmpty()) {
          <p class="checkout__empty">Der Warenkorb ist leer.</p>
        }
        @if (errorMessage(); as msg) {
          <p class="checkout__error">{{ msg }}</p>
        }

        <button type="submit" [disabled]="cartIsEmpty() || submitting()">Bestellung abschließen</button>
      </form>
    }
    ```
    `required` auf den Inputs ist reine HTML5-UX-Absicherung (verhindert versehentliches Absenden leerer Felder in der Browser-UI); die verbindliche Pflichtfeld-Prüfung liegt serverseitig in `CreateOrderRequestDto` (Task 3) — der Client wird hier nicht als Validierungsquelle vertraut (Design Paradigm: „server-authoritative").
  - [x] Route in `app.routes.ts` ergänzen, gleiches Lazy-`loadComponent`-Muster wie die drei bestehenden Routen:
    ```typescript
    {
      path: 'checkout',
      loadComponent: () => import('./features/checkout/checkout').then((m) => m.Checkout)
    }
    ```

