709	+using Microsoft.EntityFrameworkCore;
710	+using seed_b_backend.Api.Data;
711	+using seed_b_backend.Api.Data.Entities;
712	+using seed_b_backend.Api.Dtos;
713	+
714	+namespace seed_b_backend.Api.Services;
715	+
716	+public class OrderService(AppDbContext db)
717	+{
718	+    public async Task<CreateOrderResult> CreateOrderAsync(CreateOrderRequestDto request)
719	+    {
720	+        if (request.Items is not { Count: > 0 })
721	+        {
722	+            return CreateOrderResult.Rejected("empty-cart", "Der Warenkorb ist leer.");
723	+        }
724	+
725	+        if (request.Items.Any(i => i.Quantity < 1))
726	+        {
727	+            return CreateOrderResult.Rejected("invalid-quantity", "Der Warenkorb enthält eine ungültige Menge.");
728	+        }
729	+
730	+        var productIds = request.Items.Select(i => i.ProductId).Distinct().ToList();
731	+        var offers = await db.Offers
732	+            .Include(o => o.Product)
733	+            .Include(o => o.Supplier)
734	+            .Where(o => productIds.Contains(o.ProductId))
735	+            .ToListAsync();
736	+        var offersByKey = offers.ToDictionary(o => (o.ProductId, o.SupplierId));
737	+
738	+        var orderItems = new List<OrderItem>();
739	+        foreach (var item in request.Items)
740	+        {
741	+            if (!offersByKey.TryGetValue((item.ProductId, item.SupplierId), out var offer))
742	+            {
743	+                return CreateOrderResult.Rejected("offer-unavailable", "Ein Angebot im Warenkorb ist nicht mehr verfügbar.");
744	+            }
745	+
746	+            orderItems.Add(new OrderItem
747	+            {
748	+                Id = Guid.NewGuid(),
749	+                ProductId = offer.ProductId,
750	+                SupplierId = offer.SupplierId,
751	+                ProductName = offer.Product!.Name,
752	+                SupplierName = offer.Supplier!.Name,
753	+                UnitPrice = offer.Price,
754	+                Quantity = item.Quantity
755	+            });
756	+        }
757	+
758	+        var order = new Order
759	+        {
760	+            Id = Guid.NewGuid(),
761	+            Name = request.Name,
762	+            Street = request.Street,
763	+            PostalCode = request.PostalCode,
764	+            City = request.City,
765	+            Country = request.Country,
766	+            Email = request.Email,
767	+            Status = "Eingegangen",
768	+            Items = orderItems
769	+        };
770	+
771	+        db.Orders.Add(order);
772	+        await db.SaveChangesAsync();
773	+
774	+        return CreateOrderResult.Success(order.Id);
775	+    }
776	+}
