1414	+  private readonly orderService = inject(OrderService);
1415	+
1416	+  readonly name = signal('');
1417	+  readonly street = signal('');
1418	+  readonly postalCode = signal('');
1419	+  readonly city = signal('');
1420	+  readonly country = signal('');
1421	+  readonly email = signal('');
