746	+            orderItems.Add(new OrderItem
747	+            {
748	+                Id = Guid.NewGuid(),
749	+                ProductId = offer.ProductId,
750	+                SupplierId = offer.SupplierId,
751	+                ProductName = offer.Product!.Name,
752	+                SupplierName = offer.Supplier!.Name,
753	+                UnitPrice = offer.Price,
754	+                Quantity = item.Quantity
755	+            });
756	+        }
