7	
8	public class OrderService(AppDbContext db)
9	{
10	    public async Task<CreateOrderResult> CreateOrderAsync(CreateOrderRequestDto request)
11	    {
12	        if (request.Items is not { Count: > 0 })
13	        {
14	            return CreateOrderResult.Rejected("empty-cart", "Der Warenkorb ist leer.");
15	        }
16	
17	        if (request.Items.Any(i => i.Quantity < 1))
18	        {
19	            return CreateOrderResult.Rejected("invalid-quantity", "Der Warenkorb enthält eine ungültige Menge.");
20	        }
21	
22	        var productIds = request.Items.Select(i => i.ProductId).Distinct().ToList();
23	        var offers = await db.Offers
24	            .Include(o => o.Product)
25	            .Include(o => o.Supplier)
26	            .Where(o => productIds.Contains(o.ProductId))
27	            .ToListAsync();
28	        var offersByKey = offers.ToDictionary(o => (o.ProductId, o.SupplierId));
29	
30	        var orderItems = new List<OrderItem>();
31	        foreach (var item in request.Items)
32	        {
33	            if (!offersByKey.TryGetValue((item.ProductId, item.SupplierId), out var offer))
34	            {
35	                return CreateOrderResult.Rejected("offer-unavailable", "Ein Angebot im Warenkorb ist nicht mehr verfügbar.");
36	            }
37	
38	            orderItems.Add(new OrderItem
39	            {
40	                Id = Guid.NewGuid(),
41	                ProductId = offer.ProductId,
